const config = $('Configuration').first().json;
const targetDomain = String(config.target_domain || '').toLowerCase().replace(/^www\./, '');
const checkedAt = new Date().toISOString().slice(0, 10);
const rows = [];

for (const item of $input.all()) {
  const page = item.json;
  const keyword = (page.searchQuery && page.searchQuery.term) ? page.searchQuery.term : '';
  const results = Array.isArray(page.organicResults) ? page.organicResults : [];

  for (let i = 0; i < results.length; i++) {
    const r = results[i];
    let domain = '';
    try {
      domain = new URL(r.url).hostname.toLowerCase().replace(/^www\./, '');
    } catch (e) {
      domain = '';
    }

    rows.push({
      json: {
        checked_at: checkedAt,
        keyword: keyword,
        rank: r.position || (i + 1),
        title: r.title || '',
        url: r.url || '',
        domain: domain,
        description: r.description || '',
        is_target_domain: targetDomain !== '' && domain.endsWith(targetDomain)
      }
    });
  }
}

return rows;

